INSERT INTO audit_log (business_id, admin_id, admin_name, action, created_at) SELECT id, 352078684, 'Claude по просьбе владельца', 'publish', CAST(strftime('%s','now') AS INTEGER) * 1000 FROM businesses WHERE status = 'draft' AND internal_notes LIKE 'ИМПОРТ-2 25.10.2026%' AND price_ils IS NOT NULL AND city_id IS NOT NULL;
INSERT INTO broadcasts (status, business_ids, scheduled_at, created_at) SELECT 'pending', (SELECT json_group_array(id) FROM (SELECT id FROM businesses WHERE status = 'draft' AND internal_notes LIKE 'ИМПОРТ-2 25.10.2026%' AND price_ils IS NOT NULL AND city_id IS NOT NULL AND notified_at IS NULL ORDER BY lot_number)), max(CAST(strftime('%s','now') AS INTEGER) * 1000 + 120000, ifnull((SELECT max(scheduled_at) FROM broadcasts), 0) + 7200000), CAST(strftime('%s','now') AS INTEGER) * 1000 WHERE EXISTS (SELECT 1 FROM businesses WHERE status = 'draft' AND internal_notes LIKE 'ИМПОРТ-2 25.10.2026%' AND price_ils IS NOT NULL AND city_id IS NOT NULL AND notified_at IS NULL);
UPDATE businesses SET status = 'published', published_at = CAST(strftime('%s','now') AS INTEGER) * 1000 - (lot_number - 1044) * 60000, notified_at = ifnull(notified_at, CAST(strftime('%s','now') AS INTEGER) * 1000), updated_at = CAST(strftime('%s','now') AS INTEGER) * 1000, updated_by = 352078684 WHERE status = 'draft' AND internal_notes LIKE 'ИМПОРТ-2 25.10.2026%' AND price_ils IS NOT NULL AND city_id IS NOT NULL;
